var $bm_rt;
var st, end, loopTime, startTime, t, t, t1, t1, t2, t2, t2;
st = key(1).time;
end = key(numKeys).time;
$bm_rt = loopTime = $bm_sub(end, st);
if (loopTime != 0) {
    startTime = $bm_sub(time, st);
    if (startTime >= 0) {
        t = $bm_mod(startTime, loopTime);
    } else {
        t = $bm_sum(loopTime, $bm_mod(startTime, loopTime));
    }
    if (startTime >= 0) {
        t1 = $bm_mod(startTime, $bm_mul(loopTime, 2));
    } else {
        t1 = $bm_sum($bm_mul(loopTime, 2), $bm_mod(startTime, $bm_mul(loopTime, 2)));
    }
    if (startTime >= 0 && t1 >= loopTime) {
        t2 = $bm_sub(loopTime, t);
    } else if (startTime < 0 && t1 > loopTime) {
        t2 = $bm_sub(loopTime, t);
    } else {
        t2 = t;
    }
    $bm_rt = valueAtTime($bm_sum(st, t2));
}

